package com.wandertrace.controller;import com.wandertrace.dto.*;import com.wandertrace.dto.ContentDtos.*;import com.wandertrace.security.CurrentUser;import com.wandertrace.service.DestinationService;import jakarta.servlet.http.HttpSession;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;
@RestController public class DestinationController {private final DestinationService service;private final CurrentUser current;public DestinationController(DestinationService s,CurrentUser c){service=s;current=c;}private UUID user(HttpSession s){return current.require(s);}@GetMapping("/api/trips/{tripId}/destinations")ApiResponse<List<Destination>>list(@PathVariable UUID tripId,HttpSession s){return ApiResponse.ok(service.list(user(s),tripId));}@PostMapping("/api/trips/{tripId}/destinations")@ResponseStatus(HttpStatus.CREATED)ApiResponse<Destination>create(@PathVariable UUID tripId,@Valid @RequestBody DestinationRequest r,HttpSession s){return ApiResponse.ok(service.create(user(s),tripId,r));}@GetMapping("/api/destinations/{id}")ApiResponse<Destination>get(@PathVariable UUID id,HttpSession s){return ApiResponse.ok(service.get(user(s),id));}@PutMapping("/api/destinations/{id}")ApiResponse<Destination>update(@PathVariable UUID id,@Valid @RequestBody DestinationRequest r,HttpSession s){return ApiResponse.ok(service.update(user(s),id,r));}@DeleteMapping("/api/destinations/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)void delete(@PathVariable UUID id,HttpSession s){service.delete(user(s),id);}}
